INSERT INTO `countries` (`name`, `sigla`, `description`, `flag`, `updatedAt`) VALUES
('Andorra', 'AD', 'Andorra, pronúncia local: [anˈdɔra]), oficialmente Principado de Andorra, e por vezes Principado dos Vales de Andorra, é um microestado soberano europeu, sem acesso ao mar, na Península Ibérica, nos Pirenéus orientais, limitado pela França ao norte e pela Espanha ao sul. Acredita-se que tenha sido criada por Carlos Magno, sendo governada pelo Condado de Urgel até 988, quando foi transferida para a Diocese de Urgel, com o principado atual sendo formado por um tratado denominado Paréage em 1278, sendo separado do Principado da Catalunha após 1715. É conhecido como um principado, pois é uma diarquia liderada por dois copríncipes: o bispo católico de Urgel na Catalunha, Espanha e o presidente da República Francesa.', 'https://flags.restcountries.com/v5/w640/ad.png', NOW()),
('Emirados Árabes Unidos', 'AE', 'Os Emirados Árabes Unidos são uma confederação árabe localizada no Golfo Pérsico, formada por monarquias, cada uma detendo sua soberania, chamadas emirados. Os Emirados Árabes Unidos estão situados no sudeste da península Arábica e fazem fronteira com Omã e com a Arábia Saudita. Os sete emirados são Abu Dabi, Dubai, Xarja, Ajmã, Caluão, Recoima e Fujeira. A capital e a segunda maior cidade dos Emirados Árabes Unidos é Abu Dabi. A cidade também é o centro de atividades políticas, industriais e culturais.', 'https://flags.restcountries.com/v5/w640/ae.png', NOW()),
('Antígua e Barbuda', 'AG', 'Antígua e Barbuda ), ou, mais raramente, Antiga e Barbuda, é um país independente das Américas constituído por 37 ilhas situadas entre o mar do Caribe (português brasileiro) e o Oceano Atlântico. É constituída por duas grandes ilhas, Antiga e Barbuda, e outras seis ilhotas: Great Bird, Green, Guinea, Long, Maiden e York; além de outras 29 ilhotas desabitadas. Separada por poucas milhas marítimas, o arquipélago faz parte das ilhas de Barlavento das Pequenas Antilhas, na América central; cerca de 17° norte da linha do Equador.', 'https://flags.restcountries.com/v5/w640/ag.png', NOW()),
('Albânia', 'AL', 'A Albânia, oficialmente República da Albânia, é um pequeno país montanhoso da península Balcânica, no sudeste da Europa. Tem uma área total de 28,748 km² e uma população de quase 3 milhões de habitantes.', 'https://flags.restcountries.com/v5/w640/al.png', NOW()),
('Armênia', 'AM', 'Arménia (português europeu) ou Armênia (português brasileiro), denominada oficialmente República da Arménia (português europeu) ou Armênia (português brasileiro), é um país sem costa marítima, localizado numa região montanhosa na Eurásia, entre o mar Negro e o mar Cáspio, no sul do Cáucaso. Faz fronteira com a Turquia a oeste, Geórgia a norte, Azerbaijão a leste, e com o Irão e com o enclave de Naquichevão ao sul. É considerado um país transcontinental, sendo que para as Nações Unidas a Arménia está localizada na Ásia Ocidental e esta classificação também é usada pela CIA no World Factbook, apesar de o país ter extensas relações sociopolíticas, históricas e culturais com a Europa.', 'https://flags.restcountries.com/v5/w640/am.png', NOW()),
('Angola', 'AO', 'Angola, oficialmente República de Angola, é um país da costa ocidental da África Austral, cujo território tem uma área total de 1 246 700 km², sendo o sétimo maior país de África e o vigésimo segundo do mundo, com uma população estimada em 36,6 milhões de pessoas em 2024. A capital e maior cidade é Luanda, centro económico e político do país. Banhada pelo Oceano Atlântico a oeste, Angola tem um litoral de 1 650 km, sendo o territórial principal limitado a norte e a nordeste pela República Democrática do Congo, a leste pela Zâmbia e a sul pela Namíbia. O país inclui também o exclave de Cabinda, através do qual faz fronteira com a República do Congo.', 'https://flags.restcountries.com/v5/w640/ao.png', NOW()),
('Argentina', 'AR', 'Argentina oficialmente República Argentina, é o segundo maior país da América do Sul em território e o terceiro em termos de população, constituída como uma federação de 23 províncias e uma cidade autônoma, Buenos Aires, capital do país. É o oitavo maior país do mundo em área territorial e o maior entre as nações de língua espanhola, embora México, Colômbia e Espanha, que possuem menor território, sejam mais populosos.', 'https://flags.restcountries.com/v5/w640/ar.png', NOW()),
('Áustria', 'AT', 'A Áustria ), oficialmente República da Áustria, é um país de cerca de 9 milhões de habitantes, localizado na Europa Central. É limitada pela Alemanha e Chéquia (Tchéquia) a norte, Eslováquia e Hungria a leste, Eslovênia e Itália a sul, e Suíça e Liechtenstein a oeste. O seu território abrange 83 872 quilômetros quadrados e é influenciado por um clima temperado e alpino. O terreno é muito montanhoso, devido à presença dos Alpes; apenas 32% do país é inferior a 500 metros de altitude e seu ponto culminante chega aos 3 797 metros. A maioria da população fala alemão, que também é língua oficial do país. Outros idiomas regionais reconhecidos são croata, húngaro e esloveno.', 'https://flags.restcountries.com/v5/w640/at.png', NOW()),
('Austrália', 'AU', 'Austrália, oficialmente Comunidade da Austrália, é um país do hemisfério sul, localizado na Oceania, que compreende a menor área continental do mundo, a ilha da Tasmânia e várias ilhas adjacentes nos oceanos Índico e Pacífico. O continente-ilha, como a Austrália por vezes é chamada, é banhado pelo oceano Índico, ao sul, e a oeste pelo mar de Timor, mar de Arafura e Estreito de Torres, a norte, e pelo mar de Coral e mar da Tasmânia, a leste. Através destes mares, tem fronteira marítima com a Indonésia, Timor-Leste e Papua-Nova Guiné, a norte, e com o território francês da Nova Caledónia, a leste, e a Nova Zelândia a sudeste.', 'https://flags.restcountries.com/v5/w640/au.png', NOW()),
('Azerbaijão', 'AZ', 'Azerbaijão, oficialmente República do Azerbaijão, é um país transcontinental na região do Cáucaso, situado no cruzamento entre o Leste Europeu e o Sudoeste Asiático. É delimitado pelo Mar Cáspio ao leste, a Rússia ao norte, a Geórgia a noroeste, Armênia no oeste e o Irã ao sul. O exclave de Naquichevão é delimitado pela Armênia a norte e leste, pelo Irã ao sul e oeste, e possui uma pequena fronteira com a Turquia a noroeste.', 'https://flags.restcountries.com/v5/w640/az.png', NOW()),
('Bósnia e Herzegovina', 'BA', 'A Bósnia e Herzegovina ou Bósnia-Herzegovina é um país do sudeste da Europa. Situado na Península Balcânica, faz fronteira com a Sérvia a leste, Montenegro a sudeste e Croácia a norte e sudoeste, com uma costa de 20 quilômetros no Mar Adriático, a sul. A Bósnia tem um clima continental moderado, com verões quentes e invernos frios e com neve. Sua geografia é predominantemente montanhosa, especialmente nas regiões central e oriental, dominadas pelos Alpes Dináricos. A Herzegovina, região menor ao sul, tem clima mediterrâneo e é predominantemente montanhosa. Sarajevo é a capital e a maior cidade do país.', 'https://flags.restcountries.com/v5/w640/ba.png', NOW()),
('Barbados', 'BB', 'Barbados é um país insular nas Pequenas Antilhas das Índias Ocidentais, na região caribenha das Américas e a mais oriental das ilhas do Caribe. Tem 34 km de comprimento e 23 km de largura, cobrindo uma área de 432 km². Situa-se na parte ocidental do Atlântico Norte, a leste do Mar do Caribe, na borda da Placa do Caribe. Localiza-se a leste das Ilhas Barlavento, parte das Pequenas Antilhas, a aproximadamente 13° N da linha do Equador. Localizado a cerca de 168 km a leste de ambos os países de Santa Lúcia e São Vicente e Granadinas e 180 km a sudeste da Martinica e 400 km a nordeste de Trindade e Tobago, as ilhas de Barbados estão fora do principal cinturão de furacões do Atlântico. Sua capital e maior cidade é Bridgetown.', 'https://flags.restcountries.com/v5/w640/bb.png', NOW()),
('Bangladesh', 'BD', 'Bangladesh, (em bengali: বাংলাদেশ; etimologicamente: Nação Bengali), oficialmente República Popular do Bangladesh (em bengali: গণপ্রজাতন্ত্রী বাংলাদেশ;  Gônôprôjatôntri Bangladesh), é um país asiático, rodeado quase por inteiro pela Índia, exceto a sudeste, onde tem uma pequena fronteira terrestre com Myanmar, e ao sul, onde tem litoral no golfo de Bengala. O país está listado entre as economias do grupo "Próximos Onze". A capital do país é Daca. O nordeste da Índia tem fronteiras com o Bangladesh em três lados. Muitos dos aspectos físicos e culturais do Bangladesh são partilhados com Bengala Ocidental, um estado da Índia vizinho do Bangladesh. Na verdade, o Bangladesh e Bengala Ocidental formam uma região da Ásia conhecida como Bengala. Bangladesh era antigamente conhecido pelo nome de Bengala Oriental. O atual nome Bangladesh significa "nação bengali" ou "nação de Bengala". Existe vida vegetal em abundância no clima quente e úmido da região. A maior parte do país é composta por planícies baixas, fertilizadas pelas enchentes dos rios e cursos d''água que as cruzam. Os rios, durante a época das cheias, depositam solo fértil ao longo de suas margens. Mas muitas dessas enchentes também causam grande destruição nos vilarejos rurais.', 'https://flags.restcountries.com/v5/w640/bd.png', NOW()),
('Bélgica', 'BE', 'Bélgica ; em francês: Belgique [bɛlʒik]  ; em alemão: Belgien [ˈbɛlɡiən]  ), oficialmente Reino da Bélgica, é um país situado na Europa ocidental. É um dos membros fundadores da União Europeia (UE), inclusive hospedando a sede, bem como as de outras grandes organizações internacionais, como a Organização do Tratado do Atlântico Norte (OTAN). A Bélgica tem uma área de 30 528 quilômetros quadrados e uma população de cerca de 11,8 milhões de habitantes.', 'https://flags.restcountries.com/v5/w640/be.png', NOW()),
('Burkina Fasso', 'BF', 'Burquina Fasso, Burquina Faso, Burkina Faso ou simplesmente Burquina, é um país africano limitado a oeste e a norte pelo Mali, a leste pelo Níger, e a sul pelo Benim, pelo Togo, por Gana e pela Costa do Marfim. Sua capital é a cidade de Uagadugu. Sua área territorial abrange 274 200 km2 com uma população estimada de mais de 15 757 000 de habitantes.', 'https://flags.restcountries.com/v5/w640/bf.png', NOW()),
('Bulgária', 'BG', 'Bulgária, oficialmente República da Bulgária, é um país do sudeste da Europa. Faz fronteira com a Romênia a norte, a Sérvia e a Macedônia do Norte a oeste, a Grécia e a Turquia a sul, e o Mar Negro a leste. A capital e maior cidade é Sófia; outras grandes cidades são Plovdiv, Varna e Burgas. Com um território de 110 994 km², a Bulgária é o 16.º maior país da Europa.', 'https://flags.restcountries.com/v5/w640/bg.png', NOW()),
('Barein', 'BH', 'Bahrein, Barém, ou Barein, oficialmente Reino do Bahrein, é um pequeno país insular do golfo Pérsico, com fronteiras marítimas com o Irão a nordeste, com o Catar a leste e com a Arábia Saudita a sudoeste. A sua capital é Manama, a cidade mais populosa e o principal centro comercial do país. Os desertos, com sua esterilidade, cobrem mais de trinta ilhas componentes desse país árabe. É, com 780 km², a terceira menor nação na Ásia, após as Maldivas e Singapura.', 'https://flags.restcountries.com/v5/w640/bh.png', NOW()),
('Burundi', 'BI', 'O Burundi ou Burúndi, oficialmente República do Burúndi, é um pequeno país de África, encravado entre Ruanda a norte, Tanzânia a leste e a sul e a República Democrática do Congo a oeste, neste país se encontra a nascente do rio Nilo. A cidade mais populosa do país é Bujumbura, que foi a capital do Burundi até 24 de dezembro de 2018, quando a sede do governo foi transferida novamente para Guitega. Está entre os países mais pobres da África e do mundo, tendo sido classificado em 2013 como o país com o décimo menor IDH do mundo.', 'https://flags.restcountries.com/v5/w640/bi.png', NOW()),
('Benim', 'BJ', 'O Benim, oficialmente República do Benim e anteriormente conhecido como Daomé, é um país da região ocidental da África limitado a norte pelo Burquina Fasso e pelo Níger, a leste pela Nigéria, a sul pela Enseada do Benim e a oeste pelo Togo. A capital constitucional é a cidade de Porto Novo, mas Cotonu é a sede do governo e a maior cidade do país. O país tem 112 622 km² e uma população de 10 milhões de habitantes (2013).', 'https://flags.restcountries.com/v5/w640/bj.png', NOW()),
('Brunei', 'BN', 'O Brunei, oficialmente Estado de Brunei Darussalam ou Darussalã, é um Estado soberano localizado na costa norte da ilha de Bornéu, no Sudeste Asiático. Além de seu litoral com o mar da China Meridional, é completamente cercado pelo estado de Sarauaque, na Malásia, e é dividido em duas partes pelo distrito de Sarauaque, Limbang. É o único Estado soberano situado completamente na ilha de Bornéu, com o restante da ilha formando partes da Malásia e Indonésia. A população de Brunei era estimada em 423 196 em 2016.', 'https://flags.restcountries.com/v5/w640/bn.png', NOW()),
('Bolívia', 'BO', 'Bolívia, oficialmente Estado Plurinacional da Bolívia, é um país encravado no centro-oeste da América do Sul. Faz fronteira com o Brasil ao norte e leste, Paraguai e Argentina ao sul, Chile e Peru ao oeste.', 'https://flags.restcountries.com/v5/w640/bo.png', NOW()),
('Brasil', 'BR', 'Brasil, oficialmente República Federativa do Brasil, é o maior país da América do Sul e da região da América Latina, sendo o quinto maior do mundo em área territorial, com cerca de 8,5 milhões de quilômetros quadrados, e o sétimo em população. É o único país na América onde se fala majoritariamente a língua portuguesa e o maior país lusófono do planeta, além de ser uma das nações mais multiculturais e etnicamente diversas, em decorrência da forte imigração oriunda de variados locais do mundo. Sua atual constituição, promulgada em 1988, concebe o Brasil como uma república federativa presidencialista, formada pela união de 26 estados, do Distrito Federal e dos 5 571 municípios.', 'https://flags.restcountries.com/v5/w640/br.png', NOW()),
('Bahamas', 'BS', 'As Bahamas ) ou Baamas, oficialmente Comunidade das Bahamas, são um país insular membro da comunidade do Caribe constituído por mais de 700 ilhas, cayos e ilhéus no oceano Atlântico, a norte de Cuba e da ilha Espanhola, na qual se situam Haiti e República Dominicana, a noroeste do território ultramarino britânico das ilhas Turcas e Caicos e a sudeste do estado americano da Flórida. Sua capital é Nassau, na ilha de Nova Providência. Geograficamente, as Bahamas situam-se no mesmo arquipélago que Cuba, Espanhola e as ilhas Turcas e Caicos. A moeda do país é o dólar bahamense — equiparado com o dólar dos EUA.', 'https://flags.restcountries.com/v5/w640/bs.png', NOW()),
('Butão', 'BT', 'Butão, oficialmente Reino do Butão, é um país interior localizado no sul da Ásia, no extremo leste dos Himalaias. Faz fronteira a norte com a China e para o sul, leste e oeste pela Índia. Mais a oeste, está separado do Nepal pelo estado indiano de Siquim, enquanto mais ao sul está separado de Bangladesh pelos estados indianos de Assam e Bengala Ocidental. A capital e maior cidade do Butão é Thimbu.', 'https://flags.restcountries.com/v5/w640/bt.png', NOW()),
('Botsuana', 'BW', 'Botsuana ou Botswana, anteriormente Bechuana, oficialmente República do Botsuana, é um país sem costa marítima da África Austral. Anteriormente um protetorado britânico chamado Bechuanalândia, adotou seu novo nome após tornar-se independente, em 30 de setembro de 1966. Desde sua independência, o país teve governos democráticos e eleições ininterruptas, sem sofrer qualquer golpe de estado. Sua capital é Gaborone, que é também a maior cidade do país.', 'https://flags.restcountries.com/v5/w640/bw.png', NOW()),
('Belarus', 'BY', 'Bielorrússia ou Belarus, oficialmente República da Bielorrússia ou República de Belarus, é um país sem saída para o mar localizado na Europa Oriental, que faz fronteira com a Rússia a nordeste, com a Ucrânia, ao sul, com a Polônia a oeste, e com a Lituânia e Letônia a noroeste. A sua capital é Minsk, e outras de suas principais cidades são Brest, Grodno (Hrodna), Gomel (Homiel), Mogilev (Mahilyow) e Vitebsk (Viciebsk). Cerca de 40% da sua área total de 207 500 km2 é coberta por florestas, e os seus setores econômicos que mais se destacam são a agricultura e a indústria manufatureira.', 'https://flags.restcountries.com/v5/w640/by.png', NOW()),
('Belize', 'BZ', 'Belize é um país situado na costa nordeste da América Central. Faz fronteira com o México a norte, com o Mar das Caraíbas a leste e com a Guatemala a oeste e sul. Também partilha uma fronteira marítima com as Honduras a sudeste. Belize é membro da Comunidade das Caraíbas e é considerado parte da região caribenha e das históricas Índias Ocidentais Britânicas.', 'https://flags.restcountries.com/v5/w640/bz.png', NOW()),
('Canadá', 'CA', 'Canadá ; em francês: Canada, pronunciado: [kanada]) é um país que ocupa grande parte da América do Norte e se estende desde o oceano Atlântico, a leste, até o oceano Pacífico, a oeste. Ao norte o país é limitado pelo oceano Ártico. É o segundo maior país do mundo em área total, superado apenas pela Rússia, e a sua fronteira comum com os Estados Unidos, no sul e no noroeste, é a mais longa fronteira terrestre do mundo.', 'https://flags.restcountries.com/v5/w640/ca.png', NOW()),
('República Democrática do Congo', 'CD', 'República Democrática do Congo, também designada como RD Congo, Congo Democrático, Congo, Zaire ou, por vezes, Congo-Quinxassa ou Congo-Kinshasa para diferenciá-la da vizinha República do Congo é um país da África Central.', 'https://flags.restcountries.com/v5/w640/cd.png', NOW()),
('República Centro-Africana', 'CF', 'A República Centro-Africana, também chamada República da África-Central e Centráfrica, é um país localizado no centro da África, limitado a norte pelo Chade, a nordeste pelo Sudão, a leste pelo Sudão do Sul, a sul pela República Democrática do Congo e pela República do Congo, e a oeste pelos Camarões. A capital do país é a cidade de Bangui.', 'https://flags.restcountries.com/v5/w640/cf.png', NOW()),
('Congo', 'CG', 'A República do Congo, também denominada Congo ou por vezes Congo-Brazavile/Congo-Brazzaville para a distinguir da vizinha República Democrática do Congo, é um país africano limitado a norte pelos Camarões e a República Centro-Africana, a leste e a sul pela República Democrática do Congo, através do Rio Congo, a sul pelo exclave angolano de Cabinda e a oeste pelo Gabão e o Oceano Atlântico. Sua capital é a cidade de Brazavile. O Congo é um país em desenvolvimento, membro da ONU, União Africana, Comunidade Económica e Monetária da África Central, ZPCAS e da Francofonia.', 'https://flags.restcountries.com/v5/w640/cg.png', NOW()),
('Suíça', 'CH', 'Suíça, oficialmente Confederação Suíça, é uma república federal composta por 26 estados, chamados de cantões, com a cidade de Berna como a sede das autoridades federais. O país está situado na Europa Central, fazendo fronteira com a Alemanha a norte, com a França a oeste, com Itália a sul e com a Áustria e o principado de Liechtenstein a leste.', 'https://flags.restcountries.com/v5/w640/ch.png', NOW()),
('Costa do Marfim', 'CI', 'A Costa do Marfim, oficial e protocolarmente República de Côte d''Ivoire, é um país africano, limitado a norte pelo Mali e pelo Burquina Fasso, a leste pelo Gana, a sul pelo Oceano Atlântico e a oeste pela Libéria e pela Guiné. Sua capital é Iamussucro, mas a maior cidade é Abijã.', 'https://flags.restcountries.com/v5/w640/ci.png', NOW()),
('Chile', 'CL', 'Chile, oficialmente República do Chile, é um país localizado na América do Sul que ocupa uma longa e estreita faixa costeira encravada entre a cordilheira dos Andes e o Oceano Pacífico. Faz fronteira ao norte com o Peru, a nordeste com a Bolívia, a leste com a Argentina e a Passagem de Drake, a ponta mais meridional do país. O Pacífico forma toda a fronteira oeste do país, com um litoral que se estende por 6435 km. Com quase 20 milhões de habitantes, o Chile compreende alguns territórios ultramarinos, como o Arquipélago Juan Fernández, as Ilhas Desventuradas, a ilha Sala y Gómez e a ilha de Páscoa, sendo que as duas últimas estão localizadas na Polinésia. O Chile reclama a soberania de 1 250 000 quilômetros quadrados de território na Antártida. É um dos dois únicos países da América do Sul que não têm uma fronteira comum com o Brasil, junto com o Equador.', 'https://flags.restcountries.com/v5/w640/cl.png', NOW()),
('Camarões', 'CM', 'Camarões, oficialmente República dos Camarões, são um país da região ocidental da África Central. Os Camarões fazem fronteira com a Nigéria a oeste; Chade a nordeste; República Centro-Africana a leste; e Guiné Equatorial, Gabão e República do Congo, ao sul. O litoral dos Camarões encontra-se no Golfo do Biafra, parte do Golfo da Guiné e do Oceano Atlântico. O país é muitas vezes referido como "África em miniatura", pela sua diversidade geológica e cultural. Recursos naturais incluem praias, desertos, montanhas, florestas tropicais e savanas. O ponto mais alto é o Monte Camarões no sudoeste, e as cidades mais populosas são Douala, a capital Iaundé e Garoua. Os Camarões são o lar de mais de 200 grupos linguísticos diferentes. O país é conhecido por seus estilos musicais nativos, especialmente makossa e bikutsi, e pela sua bem-sucedida seleção nacional de futebol. Francês e inglês são as línguas oficiais.', 'https://flags.restcountries.com/v5/w640/cm.png', NOW()),
('China', 'CN', 'República Popular da China, também conhecida simplesmente como China, é o maior país da Ásia Oriental e o segundo país mais populoso do mundo, com mais de 1,4 bilhão de habitantes, quase um quinto da população da Terra, superado apenas pela Índia. É uma república popular socialista unipartidária. Na constituição, descreve-se como um sistema multipartidário de cooperação e consulta política sob a liderança do Partido Comunista da China e como uma "ditadura democrática popular liderada pela classe trabalhadora e baseada na aliança de trabalhadores e camponeses". Tem jurisdição sobre vinte e duas províncias, cinco regiões autônomas, quatro municípios e duas Regiões Administrativas Especiais com relativa autonomia. A capital da RPC é Pequim.', 'https://flags.restcountries.com/v5/w640/cn.png', NOW()),
('Colômbia', 'CO', 'Colômbia ), oficialmente República da Colômbia, é uma república constitucional localizada no noroeste da América do Sul. A Colômbia faz fronteira a leste com a Venezuela e Brasil; ao sul com o Equador e Peru; para o norte com o Mar do Caribe, ao noroeste com o Panamá; e a oeste com o Oceano Pacífico. A Colômbia também tem fronteiras marítimas com Venezuela, República Dominicana, Haiti, Jamaica, Honduras, Nicarágua, Costa Rica, Panamá e Equador, sendo o único país sul-americano com acesso ao Pacífico e ao Mar do Caribe. Com uma população de mais de 47 milhões de pessoas, a Colômbia tem a 28ª maior população do mundo e a segunda maior da América do Sul, depois do Brasil. A Colômbia é o segundo país mais populoso com a língua castelhana como idioma oficial, e tem a segunda maior comunidade de língua espanhola no mundo depois do México.', 'https://flags.restcountries.com/v5/w640/co.png', NOW()),
('Costa Rica', 'CR', 'Costa Rica ), oficialmente República da Costa Rica, é um país da América Central, limitado a norte pela Nicarágua, a leste pelo mar do Caribe, a sudeste pelo Panamá e a oeste pelo Oceano Pacífico. O país possui entre os seus territórios a Ilha do Coco, no Oceano Pacífico. O país possui uma população de cerca de 4,9 milhões de habitantes em uma área de terra de 51 060 km2. San José, a capital e cidade mais populosa do país, é habitada por pouco mais de 330,6 mil habitantes. A nação é conhecida por sua democracia estável em uma região marcada por instabilidades políticas e por sua força de trabalho altamente qualificada, a maioria dos quais fala a língua inglesa. O país gasta cerca de 6,9% do seu orçamento em educação, acima da média global de 4,4%. Sua economia, antes altamente dependente da agricultura, diversificou-se para incluir setores como finanças, serviços corporativos para empresas estrangeiras, produtos farmacêuticos e ecoturismo. Muitas empresas estrangeiras operam nas Zonas Francas da Costa Rica, onde se beneficiam de investimentos e incentivos fiscais. Apesar do impressionante crescimento do produto interno bruto (PIB), da inflação baixa, das taxas moderadas de juros e de um nível de desemprego aceitável, a Costa Rica enfrentou, nos últimos anos, uma crise de liquidez devido à dívida crescente e ao déficit orçamentário. Outros desafios que o país enfrenta em suas tentativas de melhorar a economia, aumentando o investimento estrangeiro, incluem uma infraestrutura precária e a necessidade de melhorar a eficiência do setor público.', 'https://flags.restcountries.com/v5/w640/cr.png', NOW()),
('Cuba', 'CU', 'Cuba, oficialmente República de Cuba, é um país insular localizado no mar do Caribe, na América Central e Caribe. É um país que compreende a ilha de Cuba, bem como a Ilha da Juventude e vários arquipélagos menores. Cuba está localizada no norte do Caribe, onde o mar do Caribe, o Golfo do México e o Oceano Atlântico se encontram. Fica a leste da Península de Iucatã (México), a sul tanto do estado norte-americano da Flórida como das Bahamas, a oeste da Hispaniola, e a norte tanto da Jamaica como das Ilhas Caimão. Havana é a maior cidade e capital; outras grandes cidades incluem Santiago de Cuba e Camagüey. A área oficial da República de Cuba é de 109 884 km2. A ilha principal de Cuba é a maior ilha de Cuba e do Caribe, com uma área de 104 338 km2. Cuba é o segundo país mais populoso do Caribe, depois do Haiti, com mais de 11 milhões de habitantes.', 'https://flags.restcountries.com/v5/w640/cu.png', NOW()),
('Cabo Verde', 'CV', 'Cabo Verde, oficialmente como República de Cabo Verde, é um país arquipelágico no Oceano Atlântico central, ao largo da costa da África Ocidental. É constituído por dez ilhas vulcânicas com uma área total de cerca de 4.033 quilómetros quadrados. Estas ilhas situam-se entre 600 e 850 quilómetros a oeste de Cabo Verde, o ponto mais ocidental de África continental, que lhes dá o nome. Cabo Verde faz parte da ecorregião da Macaronésia, juntamente com os Açores, as Ilhas Canárias, a Madeira e as Ilhas Selvagens.', 'https://flags.restcountries.com/v5/w640/cv.png', NOW()),
('Chipre', 'CY', 'Chipre, oficialmente República de Chipre é um país insular no leste do mar Mediterrâneo, ao largo das costas da Síria e Turquia. Chipre é a terceira maior e mais populosa ilha no Mediterrâneo e um Estado-membro da União Europeia desde 2004. Ele está localizado ao sul da Turquia, a oeste da Síria e do Líbano, a noroeste de Israel, ao norte do Egito e a leste da Grécia.', 'https://flags.restcountries.com/v5/w640/cy.png', NOW()),
('República Tcheca', 'CZ', 'Chéquia ou Tchéquia, oficialmente República Checa ou República Tcheca ) é um país da Europa Central, limitado ao norte pela Polónia e pela Alemanha; a leste, pela Eslováquia; ao sul, pela Áustria; a oeste, pela Alemanha. A capital do país é Praga, que também é sua maior e mais populosa cidade. A Boémia, na parte ocidental do país, é cercada por morros baixos e forma uma bacia drenada pelo Labe (Elba) e Moldava (Vltava). Morávia, a parte oriental também é montanhosa e é banhada pelo rio Morava. Silésia, a parte do norte da Morávia, entre a Morávia e a Polônia.', 'https://flags.restcountries.com/v5/w640/cz.png', NOW()),
('Alemanha', 'DE', 'Alemanha, oficialmente República Federal da Alemanha, é um país localizado na Europa Central. É limitado, a norte, pelo mar do Norte, Dinamarca e mar Báltico; a leste, pela Polônia e Chéquia; a sul, pela Áustria e Suíça e, a oeste, pela França, Luxemburgo, Bélgica e Países Baixos. O território da Alemanha abrange 357 021 quilômetros quadrados e é influenciado por um clima temperado sazonal. Com 83,5 milhões de habitantes, no final de 2025, o país tem a maior população da União Europeia e é também o lar da terceira maior população de migrantes internacionais em todo o mundo.', 'https://flags.restcountries.com/v5/w640/de.png', NOW()),
('Djibuti', 'DJ', 'O Djibuti ou Jibuti, oficialmente República do Djibuti, é um pequeno país do nordeste de África, limitado a norte pela Eritreia, a leste pelo estreito de Babelmândebe, pelo golfo de Adem e pela Somália e a sul e oeste pela Etiópia, e fronteira marítima com Iémen a nordeste. A capital é Djibuti.', 'https://flags.restcountries.com/v5/w640/dj.png', NOW()),
('Dinamarca', 'DK', 'Dinamarca é um país nórdico na porção centro-sul do Norte da Europa. É a parte metropolitana e o constituinte mais populoso do Reino da Dinamarca, um Estado constitucionalmente unitário que inclui os territórios autônomos das Ilhas Faroé e da Gronelândia no Oceano Atlântico Norte. A Dinamarca metropolitana é o mais meridional dos países escandinavos, situando-se a sudoeste e sul da Suécia, ao sul da Noruega e ao norte da Alemanha, com a qual partilha uma curta fronteira.', 'https://flags.restcountries.com/v5/w640/dk.png', NOW()),
('Dominica', 'DM', 'A Dominica é um Estado soberano insular constituído pela ilha homónima e situado no mar das Caraíbas, mais precisamente na região das Pequenas Antilhas. Os seus vizinhos são dois departamentos ultramarinos franceses: Guadalupe, a nor-noroeste, e Martinica, a sudeste. Tem uma área de 750 km², sendo o seu ponto mais alto o Morne Diablotins, com 1 447 m. A Comunidade da Dominica tem 71 293 habitantes, de acordo com o censo de 2011. A sua capital e maior cidade é Roseau.', 'https://flags.restcountries.com/v5/w640/dm.png', NOW()),
('República Dominicana', 'DO', 'A República Dominicana é uma nação na ilha de Hispaniola, parte do arquipélago das Grandes Antilhas na região do Caribe. A parte ocidental da ilha é ocupada pelo Haiti, fazendo da ilha uma das duas no Caribe, juntamente com São Martinho, que é compartilhada por dois países. Tanto por área quanto por população, a República Dominicana é o segundo maior país do Caribe, com 48 445 km2 e uma população estimada em 10 milhões de habitantes, um milhão dos quais vivem na capital, São Domingos.', 'https://flags.restcountries.com/v5/w640/do.png', NOW()),
('Argélia', 'DZ', 'Argélia ), oficialmente República Argelina Democrática e Popular, é um país da África do Norte que faz parte do Magrebe. Sua capital é Argel, no norte do país, sendo a cidade mais populosa na costa do Mediterrâneo. Com uma superfície de 2 381 741 km², é o maior país da bacia do Mediterrâneo e o mais extenso de todo continente africano, após a divisão entre o Sudão e o Sudão do Sul. Partilha as suas fronteiras terrestres ao nordeste com a Tunísia, a leste com a Líbia, ao sul com o Níger e o Mali, a sudoeste com a Mauritânia e o território contestado do Saara Ocidental, e ao oeste com Marrocos.', 'https://flags.restcountries.com/v5/w640/dz.png', NOW()),
('Equador', 'EC', 'Equador, oficialmente República do Equador, é uma república democrática representativa localizada na América do Sul, limitada a norte pela Colômbia, a leste e sul pelo Peru e a oeste pelo oceano Pacífico. É um dos dois países da região que não têm fronteiras comuns com o Brasil, além do Chile. Além do território continental, o Equador possui também as ilhas Galápagos, a cerca de 1 000 km do território continental, sendo o país mais próximo daquelas ilhas. Seu território de 256 370 km² é cortado ao meio pela imaginária linha do Equador.', 'https://flags.restcountries.com/v5/w640/ec.png', NOW()),
('Estônia', 'EE', 'A Estónia (português europeu) ou Estônia (português brasileiro), oficialmente República da Estónia é um dos três Países Bálticos, situado na Europa Setentrional, constituído por uma porção continental e um grande arquipélago no mar Báltico. Limita ao norte com o golfo da Finlândia que o separa da Finlândia, a leste limita com a Rússia, ao sul com a Letónia e a oeste com o mar Báltico, que a separa da Suécia. Tem 45 mil km2 de área e em 2000 tinha 1 376 743 habitantes. A Estónia é membro da União Europeia desde 1 de maio de 2004 e da OTAN desde 29 de março de 2004.', 'https://flags.restcountries.com/v5/w640/ee.png', NOW()),
('Egito', 'EG', 'O Egito , oficialmente República Árabe do Egito, é um país localizado entre o nordeste da África e o sudoeste da Ásia, através da Península do Sinai. É um país mediterrâneo limitado pela Faixa de Gaza e Israel a nordeste, o Golfo de Ácaba e o Mar Vermelho a leste, o Sudão ao sul e a Líbia a oeste. Do outro lado do Golfo de Ácaba fica a Jordânia, do outro lado do Mar Vermelho, a Arábia Saudita e, do outro lado do Mediterrâneo, a Grécia, a Turquia e o Chipre, embora nenhum deles tenha uma fronteira terrestre com o Egito.', 'https://flags.restcountries.com/v5/w640/eg.png', NOW()),
('Eritreia', 'ER', 'Eritreia, oficialmente Estado da Eritreia, é um país localizado no Chifre da África. Sua capital é Asmara. Faz fronteira com o Sudão a oeste, a Etiópia a sul, e Djibuti a sudeste. As partes nordeste e leste da Eritreia têm um extenso litoral ao longo do Mar Vermelho, tendo na outra margem a Arábia Saudita e o Iémen. O arquipélago de Dalaque e várias das ilhas Hanish também fazem parte da Eritreia. O país tem uma área total de 117 600 km², com uma população estimada em cerca de 5 milhões de habitantes. O nome do país é baseado no nome grego para o Mar Vermelho, que foi adotado pela primeira vez para a Eritreia italiana em 1890.', 'https://flags.restcountries.com/v5/w640/er.png', NOW()),
('Espanha', 'ES', 'Espanha ), oficialmente Reino de/da Espanha, é um país principalmente localizado na Península Ibérica na Europa. Seu território também inclui dois arquipélagos: as ilhas Canárias, na costa da África, e as ilhas Baleares, no mar Mediterrâneo. Os enclaves africanos de Ceuta e Melilla fazem da Espanha o único país europeu a ter uma fronteira terrestre com um país africano (Marrocos). Várias pequenas ilhas no mar de Alborão também fazem parte do território espanhol. A Espanha continental é limitada a sul e a leste pelo Mediterrâneo, exceto por uma pequena fronteira terrestre com Gibraltar; a norte e a nordeste pela França, por Andorra e pelo Golfo da Biscaia; e a oeste e noroeste por Portugal e pelo Oceano Atlântico. Com uma área de 505 990 km2, a Espanha é o maior país da Europa Meridional, o segundo maior país da Europa Ocidental e da União Europeia (UE) e o quarto maior país de todo o continente europeu. Também é o sexto país mais populoso da Europa e o quarto da UE. A capital e maior cidade é Madri; outras grandes áreas urbanas incluem Barcelona, Valência, Sevilha, Málaga, Bilbau e Granada.', 'https://flags.restcountries.com/v5/w640/es.png', NOW()),
('Etiópia', 'ET', 'A Etiópia, oficialmente República Democrática Federal da Etiópia e anteriormente conhecida como Abissínia, é um país encravado no Chifre da África, sendo um dos mais antigos do mundo. É a segunda nação mais populosa da África e a décima maior em área. Faz fronteira com o Sudão e com o Sudão do Sul a oeste, com o Djibuti e a Eritreia ao norte, com a Somália ao leste, e o Quênia ao sul. Sua capital é a cidade de Adis Abeba.', 'https://flags.restcountries.com/v5/w640/et.png', NOW()),
('Finlândia', 'FI', 'Finlândia, oficialmente República da Finlândia, é um país nórdico situado na região da Fino-Escandinávia, no norte da Europa. Faz fronteira com a Suécia a oeste, com a Rússia a leste e com a Noruega ao norte, enquanto a Estônia está ao sul através do Golfo da Finlândia. A capital do país e sua maior cidade é Helsinque, em finlandês Helsinki, e a segunda maior cidade é Tampere, localizada a cerca de 180 km a norte da capital. Cerca de 5,3 milhões de pessoas vivem na Finlândia, estando a maior parte concentrada no sul do país. É o oitavo maior país da Europa em extensão e o país menos densamente povoado da União Europeia. A língua materna de quase toda a população é o finlandês, que é uma das línguas fino-úgricas e é mais estreitamente relacionado com o estoniano. O finlandês é apenas uma das quatro línguas oficiais da UE que não são de origem Indo-Europeia. A segunda língua oficial da Finlândia — o sueco — é a língua nativa falada por 5,5% da população.', 'https://flags.restcountries.com/v5/w640/fi.png', NOW()),
('Fiji', 'FJ', 'A República das Fiji ou das Fíji, por vezes escrito Fidji, anteriormente conhecida como República das Ilhas Fiji, é um país insular da Oceania, composto por 332 ilhas no Oceano Pacífico. Fíji faz fronteira marítima com Tuvalu e com o território francês de Wallis e Futuna a norte, com Tonga a leste, e com o território francês da Nova Caledónia, com Vanuatu e com as Ilhas Salomão a oeste. A sul, a terra mais próxima corresponde às ilhas neozelandesas de Kermadec, mas estão bastante afastadas.', 'https://flags.restcountries.com/v5/w640/fj.png', NOW()),
('Micronésia', 'FM', 'Os Estados Federados da Micronésia, coloquialmente chamados apenas de Micronésia ), são uma nação insular da Oceania, composta por cerca de 607 ilhas que se estendem por 2 900 km pelo arquipélago das Ilhas Carolinas no oceano Pacífico, a leste das Filipinas e a norte da Papua-Nova Guiné. O país é um Estado soberano em livre associação com os Estados Unidos, país que tem total responsabilidade pela defesa dos EFM. O território do atual Estado fazia parte do Protetorado das Ilhas do Pacífico, das Nações Unidas, sob administração tutelar dos Estados Unidos. Em 1979, o país adotou uma constituição e, em 1986, a independência foi alcançada sob um Tratado de Livre Associação com os Estados Unidos.', 'https://flags.restcountries.com/v5/w640/fm.png', NOW()),
('França', 'FR', 'França, oficialmente República Francesa, é um país, ou, mais especificamente, um Estado unitário localizado na Europa Ocidental, com várias ilhas e territórios ultramarinos noutros continentes. A França Metropolitana estende-se do Mediterrâneo ao Canal da Mancha e Mar do Norte, e do rio Reno ao Oceano Atlântico. É muitas vezes referida como L''Hexagone por causa da forma geométrica do seu território e partilha fronteiras com a Bélgica e Luxemburgo a norte; Alemanha a nordeste; Suíça e Itália a leste; Espanha ao sul e com os microestados de Mônaco e Andorra. A nação é o maior país da União Europeia em área e o terceiro maior da Europa, atrás apenas da Rússia e da Ucrânia.', 'https://flags.restcountries.com/v5/w640/fr.png', NOW()),
('Gabão', 'GA', 'O Gabão, oficialmente República Gabonesa, é um país na costa equatorial ocidental da África. Limitado ao norte pelo território de Rio Muni e pelo Camarões, a leste e a sul pelo Congo-Brazavile e a oeste pelo Oceano Atlântico e pelo Golfo da Guiné, por onde é vizinho próximo de São Tomé e Príncipe e da ilha de Pagalu. Anteriormente uma colônia francesa, o Gabão se tornou independente em 1960. A capital e maior cidade é Libreville.', 'https://flags.restcountries.com/v5/w640/ga.png', NOW()),
('Reino Unido', 'GB', 'Reino Unido, oficialmente Reino Unido da Grã-Bretanha e Irlanda do Norte, é um país insular localizado em frente à costa noroeste do continente europeu. O atual Reino Unido foi formado após o surgimento do Estado Livre Irlandês em 1922, que conquistou independência da coroa britânica. O Estado soberano localiza-se na ilha da Grã-Bretanha, e na parte nordeste da ilha da Irlanda, além de muitas outras ilhas menores. A Irlanda do Norte é a única parte do Reino Unido com uma fronteira terrestre, no caso, com a República da Irlanda. Fora essa fronteira terrestre, o país é cercado pelo oceano Atlântico, o mar do Norte, o canal da Mancha e o mar da Irlanda. A maior ilha, a Grã-Bretanha, é conectada com a França pelo Eurotúnel.', 'https://flags.restcountries.com/v5/w640/gb.png', NOW()),
('Granada', 'GD', 'Granada ; em francês: La Grenade, pronunciado: [la ɡʁə.nad]) é um país caribenho, constituído pela ilha homónima e pela metade sul das ilhas Granadinas, das quais a maior é Carriacou. Tem fronteira marítima com São Vicente e Granadinas, a nordeste, e está também próxima de Trinidad e Tobago, a sudeste, e da Venezuela, a sudoeste. A capital do país é São Jorge.', 'https://flags.restcountries.com/v5/w640/gd.png', NOW()),
('Geórgia', 'GE', 'Geórgia ) é um país transcontinental localizado na fronteira entre a Europa Oriental e a Ásia Ocidental. Limita-se com a Rússia a norte e a leste, a sul com a Turquia e a Arménia, a leste e a sul com o Azerbaijão e a oeste com o mar Negro. Sua capital é Tiblíssi, que também é sua maior cidade. O país é uma república unitária, semipresidencial, com o governo eleito através de uma democracia representativa. Seu território é de 69 700 km² e sua população, conforme estimativas de 2017, é de cerca de 3,718 milhões de habitantes. Mais de um quarto da população vive na região de Tiblíssi, com outras grandes cidades sendo Cutáissi, Batumi e Rustavi.', 'https://flags.restcountries.com/v5/w640/ge.png', NOW()),
('Gana', 'GH', 'Gana é um país da África Ocidental, limitado a norte pela Burquina Fasso, a leste pelo Togo, a sul pelo Golfo da Guiné e a oeste pela Costa do Marfim. A capital e maior cidade do Gana é Acra. A palavra Gana significa "guerreiro" e é derivada do nome do antigo Império do Gana.', 'https://flags.restcountries.com/v5/w640/gh.png', NOW()),
('Gâmbia', 'GM', 'Gâmbia oficialmente República da Gâmbia, é um país da África Ocidental que rodeia o curso inferior do Rio Gâmbia. É rodeado pelo Senegal por todos os lados exceto a oeste, onde faz fronteira marítma com o Oceano Atlântico. A sua capital é Banjul, que tem a área metropolitana mais extensa em todo o país.', 'https://flags.restcountries.com/v5/w640/gm.png', NOW()),
('Guiné', 'GN', 'Guiné, oficialmente República da Guiné é um país da África Ocidental limitado a norte pela Guiné-Bissau e pelo Senegal, a norte e leste pelo Mali, a leste pela Costa do Marfim, a sul pela Libéria e pela Serra Leoa e a oeste pelo oceano Atlântico. Com 246 000 km2 e dez milhões de habitantes, a Guiné é uma república e a capital, sede do governo e maior cidade é Conacri.', 'https://flags.restcountries.com/v5/w640/gn.png', NOW()),
('Guiné Equatorial', 'GQ', 'A Guiné Equatorial, oficialmente República da Guiné Equatorial, é um país da África Central dividido em vários territórios descontínuos no golfo da Guiné: um continental, Mbini, e outros insulares. As ilhas são Bioco, no norte do Golfo do Biafra, Ano-Bom, a sul de São Tomé e Príncipe, e Corisco, Elobey Grande e Elobey Pequeno na baía de Corisco, ao largo do Gabão.', 'https://flags.restcountries.com/v5/w640/gq.png', NOW()),
('Grécia', 'GR', 'Grécia ), oficialmente República Helênica (português brasileiro) ou Helénica (português europeu) e historicamente conhecida como Hélade, é um país localizado no sul da Europa. De acordo com dados do censo de 2011, a população grega é de cerca de 11 milhões de pessoas. Atenas é a capital e a maior cidade do país.', 'https://flags.restcountries.com/v5/w640/gr.png', NOW()),
('Guatemala', 'GT', 'A Guatemala ), oficialmente República da Guatemala, é um país da América Central, limitado a oeste e a norte pelo México, a leste pelo Belize, pelo Golfo das Honduras e pelas Honduras e a sul por El Salvador e pelo Oceano Pacífico. Com uma população estimada em cerca de 18 917 714 é o país mais populoso da América Central e o 10º da América, e também a sua economia é a 9ª maior da América Latina. A Guatemala é uma democracia representativa; sua capital e maior cidade é Nueva Guatemala de la Asunción, também conhecida como Cidade da Guatemala.', 'https://flags.restcountries.com/v5/w640/gt.png', NOW()),
('Guiné-Bissau', 'GW', 'Guiné-Bissau, oficialmente República da Guiné-Bissau, é um país da África Ocidental que faz fronteira com o Senegal ao norte, Guiné-Conacri ao sul e ao leste e com o Oceano Atlântico a oeste. O território guineense abrange 36 125 km2 de área, com uma população estimada de 2 milhões de pessoas segundo o censo de 2009.', 'https://flags.restcountries.com/v5/w640/gw.png', NOW()),
('Guiana', 'GY', 'Guiana ou Guyana, oficialmente a República Cooperativa da Guiana, é um país no norte da América do Sul. É limitado pelo Oceano Atlântico ao norte, Brasil ao sul e sudoeste, Venezuela ao oeste e Suriname ao leste. Com uma área de 214 970 km², a Guiana é o terceiro menor estado soberano da América do Sul continental, depois do Uruguai e do Suriname. Com uma população estimada para 2020 de 786 559 habitantes, o país tem a segunda menor população do subcontinente, atrás apenas do Suriname.', 'https://flags.restcountries.com/v5/w640/gy.png', NOW()),
('Honduras', 'HN', 'Honduras, oficialmente República das Honduras (português europeu) ou República de Honduras (português brasileiro), é um país da América Central, limitado a norte pelo Golfo das Honduras, e a leste pelo Mar do Caribe, a sul pela Nicarágua, pelo Golfo de Fonseca e por El Salvador e a oeste pela Guatemala. Sua capital é Tegucigalpa.', 'https://flags.restcountries.com/v5/w640/hn.png', NOW()),
('Croácia', 'HR', 'Croácia, oficialmente República da Croácia, é um país europeu situado nos Balcãs que se limita ao norte com a Eslovénia e Hungria, a nordeste com a Sérvia, a leste com a Bósnia e Herzegovina e ao sul com Montenegro. É banhado a oeste pelo mar Adriático e possui uma fronteira marítima com a Itália, no golfo de Trieste.', 'https://flags.restcountries.com/v5/w640/hr.png', NOW()),
('Haiti', 'HT', 'Haiti, oficialmente República do Haiti, é um país localizado na ilha de Hispaniola, no Mar do Caribe, a leste de Cuba e Jamaica e ao sul das Bahamas. Ocupa os três oitavos ocidentais da ilha que partilha com a República Dominicana. Haiti é o terceiro maior país do Caribe, com 27 750 quilômetros quadrados de área, e tem uma população estimada de 11,4 milhões de pessoas, tornando-o o país caribenho mais populoso. A capital é Porto Príncipe.', 'https://flags.restcountries.com/v5/w640/ht.png', NOW()),
('Hungria', 'HU', 'Hungria ) é um país localizado na Europa Central, especificamente na Bacia dos Cárpatos. Faz fronteira com a Eslováquia ao norte, Romênia ao leste, Sérvia ao sul, Croácia a sudoeste, Eslovênia a oeste, Áustria a noroeste e Ucrânia a nordeste. A capital do país é a cidade de Budapeste. A Hungria é membro da União Europeia, da OTAN, da OCDE, do Grupo de Visegrád e do Espaço Schengen. A língua oficial é o húngaro, que é a língua não indo-europeia mais falada na Europa.', 'https://flags.restcountries.com/v5/w640/hu.png', NOW()),
('Indonésia', 'ID', 'Indonésia, oficialmente República da Indonésia, é um país localizado entre o Sudeste Asiático e a Austrália, sendo o maior arquipélago do mundo, composto pelas Ilhas de Sonda, a metade ocidental da Nova Guiné e compreendendo no total 17 508 ilhas. Por ser um arquipélago, tem fronteiras terrestres com a parte oriental da Malásia, Timor-Leste e Papua-Nova Guiné ; e marítimas com as Filipinas, Malásia, Singapura, Palau, Austrália e com o território indiano de Andamão e Nicobar. A localização entre dois continentes — Ásia e Oceania — faz da Indonésia uma nação transcontinental. O país é uma república, com poder legislativo e presidente eleitos por sufrágio universal, sendo sua capital a cidade de Jacarta, com uma população de cerca de 10 milhões de pessoas. É um dos membros fundadores da Associação de Nações do Sudeste Asiático (ASEAN) e membro do G20. A economia indonésia é a décima sexta maior economia do mundo e a sétima maior em paridade do poder de compra.', 'https://flags.restcountries.com/v5/w640/id.png', NOW()),
('Irlanda', 'IE', 'A Ilha da Irlanda é a terceira maior ilha da Europa e a vigésima maior do mundo. Encontra-se a noroeste da Europa continental e está cercada por centenas de ilhas e ilhéus. A leste da Irlanda localiza-se a Grã-Bretanha, separada dela pelo Mar da Irlanda. A ilha está dividida entre a República da Irlanda, que cobre um pouco menos do que cinco sextos da ilha, e a Irlanda do Norte, região sob a soberania do Reino Unido, que abrange o restante e está localizada no nordeste da ilha. Pouco menos de 5,1 milhões vivem na República da Irlanda e cerca de 1,9 milhões vivem na Irlanda do Norte. Em 2022, a população foi estimada em mais de 7 milhões de pessoas.', 'https://flags.restcountries.com/v5/w640/ie.png', NOW()),
('Israel', 'IL', 'Israel, oficialmente Estado de Israel, é um país localizado no Oriente Médio, ao longo da costa oriental do mar Mediterrâneo. Faz fronteira com o Líbano ao norte, com a Síria a nordeste, com a Jordânia e a Cisjordânia a leste, com o Egito e a Faixa de Gaza ao sudoeste, e com o golfo de Acaba, no mar Vermelho, ao sul. Geograficamente, contém diversas características dentro de seu território relativamente pequeno. Israel é definido como um "Estado Judeu e Democrático" em suas Leis Básicas e é o único Estado de maioria judaica do mundo.', 'https://flags.restcountries.com/v5/w640/il.png', NOW()),
('Índia', 'IN', 'Índia, oficialmente denominada República da Índia, é um país da Ásia Meridional. É o país mais populoso, o sétimo maior em área geográfica e a democracia mais populosa do mundo. Delimitada ao sul pelo Oceano Índico, pelo mar da Arábia a oeste e pelo golfo de Bengala a leste, a Índia tem uma costa com 7 517 km de extensão. O país faz fronteira com Paquistão a oeste; China, Nepal e Butão ao norte e Bangladexe e Mianmar a leste. Os países insulares do Oceano Índico — Seri Lanca e Maldivas — estão localizados bem próximo da Índia.', 'https://flags.restcountries.com/v5/w640/in.png', NOW()),
('Iraque', 'IQ', 'O Iraque, oficialmente República do Iraque é um país do Oriente Médio, limitado a norte pela Turquia, a leste pelo Irã, a sul pelo Golfo Pérsico, pelo Kuwait e pela Arábia Saudita e a oeste pela Jordânia e pela Síria. Sua capital é a cidade de Bagdá, no centro do país, às margens do rio Tigre.', 'https://flags.restcountries.com/v5/w640/iq.png', NOW()),
('Irã', 'IR', 'Irã (português brasileiro) ou Irão (português europeu) ), oficialmente República Islâmica do Irã/Irão e anteriormente conhecido como Pérsia, é um país localizado na Ásia Ocidental. Tem fronteiras a norte com Arménia, Azerbaijão, Turquemenistão e Mar Cáspio; a leste com Afeganistão e Paquistão; ao sul com o Golfo Pérsico e o Golfo de Omã; a oeste com o Iraque; e a noroeste com a Turquia. Composto por uma área de 1 648 195 km2, é a segunda maior nação do Oriente Médio e a 18.ª maior do mundo. Com mais de 92 milhões de habitantes, o Irã é o 17.º país mais populoso do mundo.', 'https://flags.restcountries.com/v5/w640/ir.png', NOW()),
('Islândia', 'IS', 'Islândia ) é um país nórdico insular europeu situado no oceano Atlântico Norte. O seu território abrange a ilha homônima e algumas pequenas ilhas no oceano Atlântico, localizadas entre a Europa continental e a Groenlândia. O país tem uma população de 390 mil habitantes em uma área de cerca de 103 mil quilômetros quadrados. A sua capital e maior cidade é Reiquiavique, cuja área metropolitana abriga cerca de dois terços da população nacional. Devido à sua localização na dorsal mesoatlântica, a Islândia tem uma grande atividade vulcânica e um importante gradiente geotérmico, o que afeta muito a sua paisagem. O interior é constituído principalmente por um planalto caracterizado por campos de areia, montanhas e geleiras. Aquecida pela corrente do Golfo, a Islândia tem um clima temperado em relação à sua latitude e oferece um ambiente habitável.', 'https://flags.restcountries.com/v5/w640/is.png', NOW()),
('Itália', 'IT', 'Itália ), oficialmente República Italiana, é uma república parlamentar unitária localizada no centro-sul da Europa. Ao norte, faz fronteira com França, Suíça, Áustria e Eslovênia ao longo dos Alpes. A parte sul consiste na totalidade da península Itálica, Sicília, Sardenha, as duas maiores ilhas no mar Mediterrâneo, e muitas outras ilhas menores ficam no entorno do território italiano. Os Estados independentes de San Marino e do Vaticano são enclaves no interior da Itália, enquanto Campione d''Italia é um exclave italiano na Suíça. O território do país abrange cerca de 301 338 km² e a maior parte do seu território tem um clima temperado sazonal. Com 58,9 milhões de habitantes em 2025, é a quinta nação mais populosa da Europa e a 25.ª do mundo.', 'https://flags.restcountries.com/v5/w640/it.png', NOW()),
('Jamaica', 'JM', 'Jamaica ; pronunciado em Patoá jamaicano: Jumieka [dʒʌˈmie̯ka]) é um país insular situado no mar do Caribe, que compreende a terceira maior ilha das Grandes Antilhas. A Jamaica é o quinto maior país insular do Caribe/Caraíbas. Os povos indígenas da ilha, os taínos, chamavam-na de Xaymaca em aruaque, ou seja, a "terra da madeira e da água" ou a "terra dos mananciais".', 'https://flags.restcountries.com/v5/w640/jm.png', NOW()),
('Jordânia', 'JO', 'Jordânia, oficialmente o Reino Haxemita da Jordânia, é um país do Sudoeste Asiático localizado na margem leste do rio Jordão. Faz fronteira com a Arábia Saudita ao leste e sul, Iraque ao nordeste, Síria ao norte, Israel e Palestina ao oeste e o mar Vermelho ao extremo sul. A Jordânia está estrategicamente localizada no cruzamento da Ásia, África e Europa. Sua capital e cidade mais populosa é Amã, que também é o centro econômico e cultural do país.', 'https://flags.restcountries.com/v5/w640/jo.png', NOW()),
('Japão', 'JP', 'Japão oficialmente Estado do Japão é um país insular da Ásia Oriental. Localizado no Oceano Pacífico, a leste do Mar do Japão, da China, da Coreia do Norte, da Coreia do Sul e da Rússia, estendendo-se do Mar de Okhotsk, no norte, ao Mar da China Oriental e Taiwan, ao sul.', 'https://flags.restcountries.com/v5/w640/jp.png', NOW()),
('Quênia', 'KE', 'Quénia (português europeu) ou Quênia (português brasileiro), oficialmente República do Quénia, é um país da África Oriental, limitado a norte pelo Sudão do Sul e pela Etiópia, a leste pela Somália e pelo oceano Índico, a sul pela Tanzânia e a oeste pelo Uganda. A capital e cidade mais populosa é Nairobi. O país situa-se na linha do equador. A área do Quênia abrange 581 309 km² e o país tem uma população de cerca de 45 milhões de habitantes, de acordo com estimativas para 2014. Seu nome origina-se do Monte Quênia, seu ponto geográfico mais elevado e a segunda montanha mais alta da África.', 'https://flags.restcountries.com/v5/w640/ke.png', NOW()),
('Quirguistão', 'KG', 'Quirguistão (em quirguiz: Кыргызстан; romaniz.: Kirgistan; pronunciado: [qɯrʁɯsˈstɑn]; por vezes Quirguizistão ou ainda Quirguízia, oficialmente República Quirguiz, é um país da Ásia Central, ex-integrante da antiga União Soviética. Tem fronteira ao norte com o Cazaquistão, a oeste com o Uzbequistão, a sul com o Tajiquistão e a leste com a China. Sua capital é Bisqueque, a maior cidade do país.', 'https://flags.restcountries.com/v5/w640/kg.png', NOW()),
('Camboja', 'KH', 'Camboja ou Cambodja, oficialmente Reino do Camboja, é um Estado soberano localizado na porção sul da península da Indochina, no Sudeste Asiático. Sua área territorial é de 181 035 km², fazendo deste o 88.º maior do mundo em área. Faz fronteira com a Tailândia a noroeste, com o Laos a nordeste, com o Vietnã a leste e com o Golfo da Tailândia na porção sudoeste.', 'https://flags.restcountries.com/v5/w640/kh.png', NOW()),
('Kiribati', 'KI', 'Quiribáti, Quiribati ou Kiribati, oficialmente República de Quiribáti, é um país insular na sub-região da Micronésia, na Oceania. O estado compreende 33 ilhas, com atóis e recifes espalhados por uma vasta área ao centro do oceano Pacífico, abrangendo da Micronésia à Polinésia. É o único país do mundo com territórios nos quatro hemisférios da Terra. Apesar disso, seu território terrestre total, somado, coloca-o entre os menores países do mundo. É o primeiro país do mundo a mudar de ano, na ilha de Quiritimati, devido ao fuso horário (UTC+14), de modo que a República de Quiribáti é o país mais adiantado em questão de horário.', 'https://flags.restcountries.com/v5/w640/ki.png', NOW()),
('Comores', 'KM', 'Comores, oficialmente União das Comores,  são um país independente formado por um grupo de ilhas da África austral, localizado no extremo norte do canal de Moçambique na costa oriental da África. Sua capital e maior cidade é Moroni, na Grande Comore.', 'https://flags.restcountries.com/v5/w640/km.png', NOW()),
('São Cristóvão e Névis', 'KN', 'São Cristóvão e Neves, ou São Cristóvão e Névis, oficialmente Federação de São Cristóvão e Neves ou Névis ) é um país das Caraíbas, localizado entre as ilhas de Barlavento, é uma federação constituída por 14 paróquias, nove localizadas em São Cristóvão e cinco localizadas em Neves. É também o menor Estado soberano da América, tanto em extensão territorial quanto em número de habitantes.', 'https://flags.restcountries.com/v5/w640/kn.png', NOW()),
('Coreia do Norte', 'KP', 'Coreia do Norte, oficialmente República Popular Democrática da Coreia, é um país no leste da Ásia que constitui a parte norte da península coreana, com Pyongyang como capital e maior cidade do país. Ao norte e noroeste, o país é limitado pela China e pela Rússia ao longo dos rios Amnok e Tumen; é limitado ao sul pela Coreia do Sul, os dois países são separados pela Zona Desmilitarizada Coreana (ZDC). Os dois estados afirmam ser o governo legítimo de toda a península coreana e de suas ilhas adjacentes. A Coreia do Norte e a Coreia do Sul se tornaram membros das Nações Unidas em 1991.', 'https://flags.restcountries.com/v5/w640/kp.png', NOW()),
('Coreia do Sul', 'KR', 'Coreia do Sul, oficialmente República da Coreia, também conhecida somente como Coreia é um país do Leste Asiático, localizado na parte sul da Península da Coreia. Sua única fronteira terrestre é com a Coreia do Norte, com a qual formou apenas um país até 1945. Faz fronteira a leste com o Mar do Japão, a sul com o Estreito da Coreia, que o separa do Japão, e a oeste com o Mar Amarelo. Seu território compreende a metade sul da península coreana, englobando cerca de três mil ilhas que a rodeiam, dentre as quais se destacam Jeju, Ulleungdo e os Rochedos de Liancourt (Dokdo). A capital e maior cidade do país é Seul, cuja área metropolitana é a segunda mais populosa do mundo.', 'https://flags.restcountries.com/v5/w640/kr.png', NOW()),
('Kuwait', 'KW', 'Kuwait, oficialmente Estado do Kuwait, é um emirado árabe soberano situado no nordeste da península Arábica na Ásia Ocidental. Faz fronteira com a Arábia Saudita ao sul e ao norte com o Iraque. Encontra-se na costa noroeste do Golfo Pérsico. O nome Kuwait é derivado do árabe "akwat", o plural de "Kout", que significa "fortaleza construída perto da água". O emirado tem uma área de 17 820 km² e tem uma população de cerca de 2,7 milhões de habitantes.', 'https://flags.restcountries.com/v5/w640/kw.png', NOW()),
('Cazaquistão', 'KZ', 'O Cazaquistão, oficialmente República do Cazaquistão, é um país transcontinental, localizado na Ásia Central, com uma pequena parte a oeste do rio Ural na Europa. É o maior país sem costa marítima do mundo e o nono maior do planeta; o seu território de 2 724 900 quilômetros quadrados é maior do que a área da Europa Ocidental. O Cazaquistão tem fronteiras com Rússia, China, Quirguistão, Uzbequistão e Turcomenistão, e, ainda, detém uma grande parte litorânea do mar Cáspio. O terreno do país inclui planícies, estepes, taiga, desfiladeiros de rochas, montanhas, deltas, montanhas cobertas de neve e desertos. Com uma estimativa de 18,7 milhões de habitantes (2020), o Cazaquistão é classificado como o 63º país mais populoso do mundo, embora sua densidade populacional esteja entre as mais baixas, com 6 pessoas por km². A capital cazaque é Astana, depois que foi transferida de Almati, em 1997.', 'https://flags.restcountries.com/v5/w640/kz.png', NOW()),
('Laos', 'LA', 'O Laos, oficialmente República Democrática Popular do Laos, é um país do Sudeste Asiático, localizado na Indochina e limitado a norte pela China, a leste pelo Vietnã, a sul pelo Camboja, a sul e oeste pela Tailândia e a noroeste por Myanmar. Sua população foi estimada em 6,5 milhões de habitantes em 2012.', 'https://flags.restcountries.com/v5/w640/la.png', NOW()),
('Líbano', 'LB', 'Líbano, oficialmente República do Líbano é um país localizado na extremidade leste do mar Mediterrâneo, na Ásia Ocidental, numa região que faz ligação entre esse continente e a Europa. Faz fronteira com a Síria ao norte e a leste e com Israel ao sul e a oeste. No cruzamento da bacia do Mediterrâneo, o Líbano é uma das regiões de antigas civilizações, como fenícios, assírios, persas, gregos, romanos, bizantinos e turcos otomanos, sendo que sua rica história formou a identidade cultural única em diversidade étnica e religiosa do país.', 'https://flags.restcountries.com/v5/w640/lb.png', NOW()),
('Santa Lúcia', 'LC', 'Santa Lúcia ; em francês:  Sainte-Lucie) é um país insular das Pequenas Antilhas, no Caribe, próximo à Martinica, São Vicente e Granadinas e Barbados. Seu nome foi dado por Cristóvão Colombo, que ali esteve, em 1502.', 'https://flags.restcountries.com/v5/w640/lc.png', NOW()),
('Liechtenstein', 'LI', 'Liechtenstein ou Listenstaine, oficialmente Principado de Liechtenstein (português brasileiro) ou do Liechtenstein (português europeu), é um microestado principado localizado no centro da Europa, encravado nos Alpes entre a Áustria, a leste, e a Suíça a oeste. Pouco mais de 39 000 habitantes moram nos seus 160,477 km² segundo algumas estimativas.', 'https://flags.restcountries.com/v5/w640/li.png', NOW()),
('Sri Lanka', 'LK', 'O Sri Lanka, Sri Lanca ou Seri Lanca, oficialmente República Socialista Democrática do Sri Lanka; conhecido pela forma portuguesa equivalente Ceilão, adotada pelo país até 1972; era chamado de Taprobana na Antiguidade e na Idade Média, é um país insular asiático, localizado ao largo da extremidade sul do subcontinente indiano. Tem costas para a baía de Bengala a leste, oceano Índico a sul e a oeste, e o estreito de Palk a noroeste, que o separa da Índia. A sua capital é Seri Jaiavardenapura-Cota, subúrbio da antiga capital Colombo, desde a inauguração do novo edifício do parlamento, em 1982.', 'https://flags.restcountries.com/v5/w640/lk.png', NOW()),
('Libéria', 'LR', 'A Libéria, oficialmente República da Libéria, é uma república presidencialista localizada na África Ocidental. Faz fronteira ao norte com a Serra Leoa e Guiné, a leste com a Costa do Marfim e a sul e oeste com o Oceano Atlântico. Segundo o censo de 2008, a população do país é de 3 955 000 habitantes, divididos em uma área de 111 369 km2. A cidade de Monróvia é sua capital. A Libéria possui um clima quente equatorial, com chuvas intensas na estação chuvosa e ventos na estação seca. A vegetação é composta, na maior parte, por florestas de mangue, enquanto o interior é escassamente povoado de florestas, com predominância de pastagens secas.', 'https://flags.restcountries.com/v5/w640/lr.png', NOW()),
('Lesoto', 'LS', 'Lesoto ou Lessoto é um pequeno país da África Austral. Um enclave incrustado na África do Sul, montanhoso e sem saída para o mar, o país é o antigo reino da Basutolândia, um dos países etnicamente mais homogêneos da África: 99% de sua população é da etnia soto. O país vive da agricultura e criação de ovelhas na cordilheira do Dracoberga, que domina a maior parte do território e atingem mais de 3 mil metros de altitude. É bastante dependente da África do Sul; o dinheiro enviado por seus cidadãos empregados nas minas e fábricas sul-africanas representa 26% do PIB.', 'https://flags.restcountries.com/v5/w640/ls.png', NOW()),
('Lituânia', 'LT', 'A Lituânia, oficialmente República da Lituânia ,é um país europeu que forma uma das três repúblicas bálticas. Limita ao norte com a Letônia, ao leste e ao sul com a Bielorrússia, ao sul com a Polônia, ao sul e ao oeste com o exclave russo de Kaliningrado e ao oeste com o mar Báltico. Sua capital é a cidade de Vilnius, no leste do país. Outras cidades importantes são Kaunas e Klaipėda.', 'https://flags.restcountries.com/v5/w640/lt.png', NOW()),
('Luxemburgo', 'LU', 'Luxemburgo oficialmente Grão-Ducado do Luxemburgo ou de Luxemburgo é um pequeno país sem litoral na Europa Ocidental. Faz fronteira com a Bélgica a oeste e norte, com a Alemanha a leste e com a França ao sul. A sua capital e cidade mais populosa, Luxemburgo, é uma das quatro sedes institucionais da União Europeia e a sede de várias instituições da UE, notadamente o Tribunal de Justiça da União Europeia, a mais alta autoridade judicial. A cultura, o povo e os idiomas de Luxemburgo estão altamente interligados com seus vizinhos franceses e alemães; enquanto o luxemburguês é legalmente a única língua nacional do povo luxemburguês, o francês e o alemão também são usados em assuntos administrativos e judiciais e todos os três são considerados idiomas administrativos do país.', 'https://flags.restcountries.com/v5/w640/lu.png', NOW()),
('Letônia', 'LV', 'Letónia (português europeu) ou Letônia (português brasileiro), oficialmente República da Letónia / Letônia, é uma nação do Norte da Europa, sendo uma das três repúblicas bálticas. Faz fronteira ao norte com a Estónia, a leste com a Rússia, a sudeste com a Bielorrússia, a sul com a Lituânia e a oeste com o mar Báltico.', 'https://flags.restcountries.com/v5/w640/lv.png', NOW()),
('Líbia', 'LY', 'A Líbia, pronunciado em árabe líbio: [ˈliːbjæ]; em berbere: ) é um país na região do Magrebe, no Norte da África, banhada pelo mar Mediterrâneo ao norte. O país tem fronteiras com o Egito a leste, com o Sudão a sudeste, com o Chade e o Níger ao sul e com a Argélia e a Tunísia ao oeste. As três partes tradicionais do país são a Tripolitânia, a Fazânia e a Cirenaica. Com uma área de quase 1,8 milhões de quilômetros quadrados, a Líbia é o 17.º maior país do mundo.', 'https://flags.restcountries.com/v5/w640/ly.png', NOW()),
('Marrocos', 'MA', 'Marrocos, oficialmente Reino do Marrocos, é um país soberano localizado na região do Magrebe, no norte da África. É banhado pelo mar Mediterrâneo a norte e pelo oceano Atlântico a oeste. Faz fronteira com a Argélia a leste e sudeste, a Espanha a norte e com a Mauritânia e com o Saara Ocidental a sul. Geograficamente, o Marrocos é caracterizado por um interior montanhoso acidentado, grandes extensões de deserto e um longo litoral ao longo do oceano Atlântico e do mar Mediterrâneo.', 'https://flags.restcountries.com/v5/w640/ma.png', NOW()),
('Mônaco', 'MC', 'Mónaco, oficialmente Principado do Mónaco (português europeu) ou Principado de Mônaco (português brasileiro), é uma cidade-estado soberana, e, portanto, um microestado, situado ao sul da França. Fazendo costa com o mar Mediterrâneo, o principado, fundado em 1297 pela Casa de Grimaldi — até hoje sua soberana —, fica a menos de 20 km a leste da cidade de Nice e 20 km a oeste da cidade de Ventimiglia. Possui aproximadamente uma área de 202 ha, sendo o segundo menor Estado do mundo, atrás apenas do Vaticano, com 44 hectares de área, e é o estado com a densidade populacional mais alta do mundo. Tem como forma de governo a monarquia constitucional, em que o monarca é Sua Alteza Sereníssima, o Príncipe Alberto II do Mónaco.', 'https://flags.restcountries.com/v5/w640/mc.png', NOW()),
('Moldávia', 'MD', 'Moldávia ou Moldova, protocolarmente, República da Moldova ), é um país sem costa marítima da Europa Oriental, que faz fronteira com a Ucrânia e com a Romênia. Sua capital e maior cidade é Quixinau,.', 'https://flags.restcountries.com/v5/w640/md.png', NOW()),
('Montenegro', 'ME', 'Montenegro, literalmente "montanha negra") é uma pequena república montanhosa situada nos Balcãs, no sudeste da Europa, que faz fronteira com o mar Adriático a sudoeste, com a Albânia e o Cosovo a sudeste, com a Bósnia e Herzegovina e uma pequena fronteira com a Croácia a noroeste, e com a Sérvia a nordeste. A sua capital é a cidade de Podgoritza.', 'https://flags.restcountries.com/v5/w640/me.png', NOW()),
('Madagascar', 'MG', 'Madagáscar (português europeu) ou Madagascar (português brasileiro), oficialmente República de Madagáscar/Madagascar, anteriormente conhecida como República Malgaxe, é um país insular no Oceano Índico, que ocupa a maior ilha do continente africano, situada ao largo da costa sudeste da África.', 'https://flags.restcountries.com/v5/w640/mg.png', NOW()),
('Ilhas Marshall', 'MH', 'As Ilhas Marshall ; em marshallês: Aelōñin M̧ajeļ, pronunciado: [ɑ̯ɑ͡ɒo̯o͡ɤrˠɤɡɯ͡inʲ mˠɑɑ̯zʲɛ͡ʌɫ]), oficialmente República das Ilhas Marshall, são um país da Micronésia, cujos vizinhos mais próximos são Quiribáti, a sul, os Estados Federados da Micronésia, a oeste, e a Ilha Wake, pertencente aos Estados Unidos, a norte.', 'https://flags.restcountries.com/v5/w640/mh.png', NOW()),
('Macedônia do Norte', 'MK', 'A Macedónia (português europeu) ou Macedônia (português brasileiro) do Norte ou oficialmente República da Macedónia do Norte, é um país localizado na península balcânica, no sudeste da Europa. É um dos estados sucessores da antiga Iugoslávia, da qual declarou independência em 1991.', 'https://flags.restcountries.com/v5/w640/mk.png', NOW()),
('Mali', 'ML', 'Mali ou Máli, oficialmente República do Mali, é um país africano sem saída para o oceano na África Ocidental. É o sétimo maior país da África, e limita-se, a norte, pela Argélia, a leste pelo Níger, a oeste pela Mauritânia e Senegal e ao sul pela Costa do Marfim, Guiné e Burquina Fasso. O Mali tem uma área de 1 240 000 km² e a sua população é estimada em cerca de 24,5 milhões de habitantes. A capital do país é Bamaco.', 'https://flags.restcountries.com/v5/w640/ml.png', NOW()),
('Mianmar', 'MM', 'Myanmar ou Birmânia, oficialmente República da União de Myanmar, é um país do sul da Ásia continental, limitado ao norte e nordeste pela China; a leste pelo Laos; a sudeste pela Tailândia; ao sul e sudoeste pelo mar de Andamão e pelo golfo de Bengala; e a noroeste pelo Bangladesh e pela Índia. Em 2006, a capital do país foi transferida de Rangum para Nepiedó.', 'https://flags.restcountries.com/v5/w640/mm.png', NOW()),
('Mongólia', 'MN', 'Mongólia é um país sem costa marítima localizado na Ásia Oriental e Central. Faz fronteira com a Rússia no norte e com a China no sul, leste e oeste. Embora a Mongólia não partilhe uma fronteira com o Cazaquistão, o seu ponto mais ocidental é de apenas 38 quilômetros da ponta leste do Cazaquistão. Ulã Bator, a capital e maior cidade, é o lar de 45% da população do país. O sistema político vigente na Mongólia é de uma república semipresidencialista.', 'https://flags.restcountries.com/v5/w640/mn.png', NOW()),
('Mauritânia', 'MR', 'Mauritânia, oficialmente República Islâmica da Mauritânia, é um país soberano no noroeste da África. Faz fronteira com o Oceano Atlântico a oeste, o Saara Ocidental a norte e noroeste, a Argélia a nordeste, o Mali a leste e sudeste e o Senegal a sudoeste. Em termos de área territorial, a Mauritânia é o 11º maior país da África e o 28º maior do mundo; 90% do seu território está no Saara. A maior parte da sua população, cerca de 4,3 milhões, vive no sul temperado do país, com cerca de um terço concentrado na capital e maior cidade, Nuaquexote, na costa atlântica.', 'https://flags.restcountries.com/v5/w640/mr.png', NOW()),
('Malta', 'MT', 'Malta, oficialmente República de Malta ), é um país insular localizado no Sul da Europa, cujo território ocupa as Ilhas Maltesas, um arquipélago situado no Mar Mediterrâneo, 93 km ao sul da ilha da Sicília (Itália) e 288 km a nordeste da Tunísia (África), 1 826 km a leste de Gibraltar e 1 510 km a oeste de Alexandria.', 'https://flags.restcountries.com/v5/w640/mt.png', NOW()),
('Maurício', 'MU', 'Maurícia (português europeu) ou Maurício (português brasileiro), oficialmente República da Maurícia (português europeu) ou República de Maurício (português brasileiro), é um país insular do oceano Índico, a cerca de 2 000 km da costa sudeste do continente africano. O país inclui as ilhas Maurícia e Rodrigues, 560 km a leste da ilha Maurícia, e as ilhas exteriores. O país também reivindica o Arquipélago de Chagos, que faz parte do Território Britânico do Oceano Índico, e também reivindica a ilha de Tromelin, que faz parte das Terras Austrais e Antárticas Francesas. As ilhas Maurícia e Rodrigues fazem parte das Ilhas Mascarenhas, junto com a vizinha Reunião, um departamento ultramarino francês. A área do país é de 2 040 km². A capital e maior cidade é Porto Luís. O país é membro da Comunidade das Nações, da Francofonia e da União Africana.', 'https://flags.restcountries.com/v5/w640/mu.png', NOW()),
('Maldivas', 'MV', 'A República das Maldivas é um pequeno país insular situado no oceano Índico ao sudoeste do Sri Lanca e da Índia, ao sul do continente asiático, constituído por 1 196 ilhas, das quais 203 são habitadas, localizadas a cerca de 450 km ao sul da península do Decão. A sua única fronteira real é com o território indiano das Laquedivas, a norte, mas são também os vizinhos mais próximos do Arquipélago de Chagos, um conjunto de ilhas localizadas ao sul das Maldivas.', 'https://flags.restcountries.com/v5/w640/mv.png', NOW()),
('Malaui', 'MW', 'O Malawi ou Maláui, oficialmente República do Malawi, é um país da África Oriental, limitado a norte e a leste pela Tanzânia, a leste, sul e oeste por Moçambique e a oeste pela Zâmbia. Sua capital é Lilongué. Parte da região oriental do país é banhada pelo Lago Niassa. O inglês é a língua oficial.', 'https://flags.restcountries.com/v5/w640/mw.png', NOW()),
('México', 'MX', 'México, oficialmente Estados Unidos Mexicanos, é uma república constitucional federal localizada na América do Norte. O país é limitado a norte pelos Estados Unidos; ao sul e oeste pelo Oceano Pacífico; a sudeste pela Guatemala, Belize e Mar do Caribe; a leste pelo Golfo do México. Com um território que abrange quase 2 milhões de quilômetros quadrados, o México é o quinto maior país da América por área total e o 14.º maior país independente do mundo. Com uma população estimada para 2020 de 126 milhões de habitantes, é o 11.º país mais populoso do mundo e o mais populoso país da hispanofonia. O México é uma federação composta por 31 estados e a Cidade do México (capital). O México figura também como o segundo país mais populoso e segundo em PIB da América Latina, em ambos os casos superado apenas pelo Brasil.', 'https://flags.restcountries.com/v5/w640/mx.png', NOW()),
('Malásia', 'MY', 'Malásia é um país do Sudeste Asiático que compreende dois territórios distintos: a parte sul da península Malaia e ilhas adjacentes, e uma seção do norte da ilha de Bornéu. A península da Malásia confina a norte com a Tailândia, a leste com o mar da China Meridional, e a sul e a oeste com o estreito de Malaca, fazendo fronteiras marítimas com a Indonésia, a leste, sul e oeste, com Singapura a sul e com o Vietnã a nordeste. A Malásia Insular limita a oeste e a norte com o mar da China Meridional, a norte com o Brunei, a leste com o mar de Sulu e a sul com a Indonésia, fazendo fronteira marítima com as Filipinas a norte e a leste. A capital do país é Kuala Lumpur, sendo Putrajaia a sede do governo federal.', 'https://flags.restcountries.com/v5/w640/my.png', NOW()),
('Moçambique', 'MZ', 'Moçambique, oficialmente designado como República de Moçambique, é um país localizado no sudeste do continente africano, banhado pelo Oceano Índico a leste e que faz fronteira com a Tanzânia ao norte; Maláui e Zâmbia a noroeste; Zimbábue a oeste e Essuatíni e África do Sul a sudoeste. A capital e maior cidade do país é Maputo, anteriormente chamada de Lourenço Marques, durante o domínio português.', 'https://flags.restcountries.com/v5/w640/mz.png', NOW()),
('Namíbia', 'NA', 'Namíbia, oficialmente República da Namíbia é um país da África Austral limitado a norte por Angola e Zâmbia, a leste pelo Botsuana, a sul pela África do Sul e a oeste pelo oceano Atlântico. Embora não faça fronteira com o Zimbábue, menos de 200 metros da fronteira com a Zâmbia e Botsuana separa-os em seus pontos mais próximos. O país ganhou a independência da África do Sul em 21 de março de 1990, após a Guerra de Independência da Namíbia. Sua capital e maior cidade é Vinduque. A Namíbia é um país membro da Organização das Nações Unidas (ONU), da Comunidade para o Desenvolvimento da África Austral (SADC), da União Africana (UA) e da Comunidade das Nações (Commonwealth).', 'https://flags.restcountries.com/v5/w640/na.png', NOW()),
('Níger', 'NE', 'Níger, oficialmente República do Níger, é um país da África Ocidental. Faz fronteira com a Argélia e Líbia ao norte, a leste com o Chade, a sul com a Nigéria e Benim e a oeste com Burquina Fasso e Mali. O país abrange uma área de quase 1 270 000 km², fazendo desta a maior nação da África Ocidental, com mais de 75% de sua área de terra coberta pelo Deserto do Saara. A população é predominantemente islâmica, sendo estimada em 17 138 707 habitantes, conforme dados de 2013. A capital é Niamei, localizado no sudoeste do país, que é a sua cidade mais populosa.', 'https://flags.restcountries.com/v5/w640/ne.png', NOW()),
('Nigéria', 'NG', 'A Nigéria, oficialmente República Federal da Nigéria, é uma república constitucional federal que compreende 36 estados e o Território da Capital Federal. O país está localizado na África Ocidental e compartilha fronteiras terrestres com o Benim a oeste; com Chade e Camarões a leste, e com o Níger ao norte. Sua costa encontra-se ao sul, no Golfo da Guiné, no Oceano Atlântico.', 'https://flags.restcountries.com/v5/w640/ng.png', NOW()),
('Nicarágua', 'NI', 'A Nicarágua, oficialmente República da Nicarágua, é um país da América Central, limitado ao norte pelo Golfo de Fonseca e fronteira terrestre com Honduras. É banhada ao leste pelo Mar das Caraíbas, através do qual faz fronteira marítima com o território colombiano de San Andrés e Providencia, a sul com a Costa Rica e a oeste com o Oceano Pacífico. Sua capital é Manágua.', 'https://flags.restcountries.com/v5/w640/ni.png', NOW()),
('Países Baixos', 'NL', 'Países Baixos (em neerlandês: Nederland AFI: [ˈneːdərˌlɑnt]  , literalmente "país baixo"), informalmente conhecidos como Holanda, são uma nação constituinte do Reino dos Países Baixos localizada na Europa ocidental. O país é uma monarquia constitucional parlamentar democrática banhada pelo mar do Norte a norte e a oeste, que faz fronteira com a Bélgica a sul e com a Alemanha a leste. A capital é Amesterdãopt ou Amsterdãbr e a sede do governo é na cidade de Haia.', 'https://flags.restcountries.com/v5/w640/nl.png', NOW()),
('Noruega', 'NO', 'Noruega, oficialmente Reino da Noruega, é um país nórdico, situado na Europa do Norte, onde ocupa a parte ocidental da Península Escandinava.
